// ===========================================
// AES-256 (256-bit key, 14 rounds)
// Added for Kakao TLS_AES_256_GCM_SHA384
// ===========================================

pub(crate) fn key_expansion_256(key: [u8; 32]) -> [[u8; 4]; 60] {
    let mut key_expanded: [[u8; 4]; 60] = [[0; 4]; 60];

    // First 8 words = key
    for i in 0..8 {
        let mut temp = [0; 4];
        for j in 0..4 {
            temp[j] = key[i * 4 + j];
        }
        key_expanded[i] = temp;
    }

    // i in 8..60
    for round in 8..60 {
        let mut temp = key_expanded[round - 1];
        if round % 8 == 0 {
            temp = sub_word(rot_word(temp));
            temp = word_xor(temp, round_constant((((round / 8) - 1) as u8)));
        } else if round % 8 == 4 {
            temp = sub_word(temp);
        }
        key_expanded[round] = word_xor(key_expanded[round - 8], temp);
    }

    key_expanded
}

pub fn aes_256(block: Block, key: [u8; 32]) -> Block {
    let key_expanded = key_expansion_256(key);
    let first_round_key: Block = [key_expanded[0], key_expanded[1], key_expanded[2], key_expanded[3]];
    let mut state = add_round_key(block, first_round_key);

    for round in 1..14 {
        state = sub_bytes(state);
        state = shift_rows(state);
        state = mix_columns(state);
        let round_key: Block = [
            key_expanded[round * 4],
            key_expanded[round * 4 + 1],
            key_expanded[round * 4 + 2],
            key_expanded[round * 4 + 3],
        ];
        state = add_round_key(state, round_key);
    }

    state = sub_bytes(state);
    state = shift_rows(state);
    let final_round_key: Block = [key_expanded[56], key_expanded[57], key_expanded[58], key_expanded[59]];
    state = add_round_key(state, final_round_key);
    state
}

#[test]
fn test_aes_256_nist() {
    // NIST FIPS-197 Appendix C.3 test vector
    // Plaintext:  00112233445566778899aabbccddeeff
    // Key:        000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f
    // Ciphertext: 8ea2b7ca516745bfeafc49904b496089
    let block: Block = [
        [0x00, 0x44, 0x88, 0xcc],
        [0x11, 0x55, 0x99, 0xdd],
        [0x22, 0x66, 0xaa, 0xee],
        [0x33, 0x77, 0xbb, 0xff],
    ];
    let key: [u8; 32] = [
        0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
        0x08, 0x09, 0x0a, 0x0b, 0x0c, 0x0d, 0x0e, 0x0f,
        0x10, 0x11, 0x12, 0x13, 0x14, 0x15, 0x16, 0x17,
        0x18, 0x19, 0x1a, 0x1b, 0x1c, 0x1d, 0x1e, 0x1f,
    ];
    let cipher: Block = [
        [0x8e, 0x51, 0xea, 0x4b],
        [0xa2, 0x67, 0xfc, 0x49],
        [0xb7, 0x45, 0x49, 0x60],
        [0xca, 0xbf, 0x90, 0x89],
    ];
    assert(aes_256(block, key) == cipher);
}

